getFieldRegistry:
/**
 * Get the field registry singleton.
 * Backed by globalThis to survive Vite pre-bundling chunk splits and HMR.
 */
export declare function getFieldRegistry(): FieldRegistry;

registerFieldType:
/**
 * Register a custom field type (form, optional display, optional filter).
 * Schema must be defined in entity.validation.schema
 *
 * @example
 * ```ts
 * import { useController, registerFieldType } from '@donotdev/crud';
 * import type { ControlledFieldProps } from '@donotdev/crud';
 * import * as v from 'valibot';
 *
 * function ControlledRepairOperationsField({
 *   fieldConfig,
 *   control,
 *   errors,
 *   t,
 * }: ControlledFieldProps) {
 *   const { field, fieldState } = useController({
 *     name: fieldConfig.name,
 *     control: control,
 *   });
 *   return (
 *     <div>
 *       Your custom UI here
 *       {fieldState?.error && <span>{fieldState.error.message}</span>}
 *     </div>
 *   );
 * }
 *
 * registerFieldType({
 *   type: 'repairOperations',
 *   controlledComponent: ControlledRepairOperationsField,
 *   displayFormatter: (value) => (value != null ? String(value) : '—'),
 *   filterable: true,
 *   filterType: 'text',
 * });
 *
 * const carEntity = defineEntity({
 *   fields: {
 *     repairs: {
 *       type: 'repairOperations',
 *       validation: { schema: v.array(v.object({ operation: v.string(), cost: v.number() })) }
 *     }
 *   }
 * });
 * ```
 */
export declare function registerFieldType<FT extends FieldType>(registration: FieldTypeRegistration<FT>): void;

isFieldTypeRegistered:
/**
 * Check if a field type is registered
 */
export declare function isFieldTypeRegistered(type: string): boolean;

registerBuiltinFieldType:
/**
 * Register a built-in field type with all metadata.
 * For internal/plugin use — consumers should use registerFieldType() instead.
 */
export declare function registerBuiltinFieldType(metadata: FieldTypeMetadata): void;

useController:
/**
 * Framework-provided useController hook
 *
 * Use this instead of importing useController from react-hook-form directly.
 * This ensures type compatibility with framework's Control types.
 *
 * @template TFieldValues - Form values type
 * @template TName - Field name path
 * @param props - Controller props (name and control)
 * @returns Controller return value (field, fieldState, formState)
 *
 * @example
 * ```tsx
 * import { useController } from '@donotdev/crud';
 * import type { ControlledFieldProps } from '@donotdev/crud';
 *
 * function MyCustomField({ control, fieldConfig }: ControlledFieldProps) {
 *   const { field, fieldState } = useController({
 *     name: fieldConfig.name,
 *     control: control,
 *   });
 *   // ...
 * }
 * ```
 */
export declare function useController<TFieldValues extends FieldValues = FieldValues, TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>>(props: UseControllerProps<TFieldValues, TName>): UseControllerReturn<TFieldValues, TName>;

useFormDraftState:
/**
 * Page state saved in the form's draft: autosaved with it, saved at submit,
 * restored with it ("Draft restored" toast), reset by its Discard, cleared when
 * the submit succeeds and kept when it fails. A value different from `initial`
 * is an edit: it keeps the draft like a dirty field. Values must be JSON-serializable.
 *
 * @param form - The `useEntityForm` result that owns the page Save
 * @param key - Slot name, unique within the form
 * @param initial - Value when no draft exists (and after Discard)
 * @param options - See {@link UseFormDraftStateOptions}
 * @returns `[value, setValue]`, like `useState`
 *
 * @example
 * ```tsx
 * const form = useEntityForm(routineEntity, { formId: 'routine', operation: 'edit', defaultValues });
 * const [productIds, setProductIds] = useFormDraftState(form, 'productIds', initialIds, {
 *   parse: (draft) => v.parse(v.array(v.string()), draft),
 * });
 * const save = form.handleSubmit((values) => saveRoutine(values, productIds));
 * ```
 */
export declare function useFormDraftState<T>(form: {
    draftState: FormDraftStateRegistry;
}

EMPTY_VALUE:
/**
 * The form-state value of a field that is not filled in.
 *
 * @since 0.2.4
 */
export declare const EMPTY_VALUE: null;

validateEntity:
/**
 * Validates data against an entity definition.
 *
 * Uses Valibot under the hood with entity-derived schemas.
 * Pure function, no React dependencies.
 *
 * @template E - Entity type from defineEntity()
 * @param entity - Entity definition from defineEntity()
 * @param data - Data to validate
 * @param operation - Validation context ('create', 'draft', 'update', or 'full')
 * @returns Validation result with typed issues
 *
 * @example
 * ```typescript
 * import { validateEntity } from '@donotdev/crud/forms';
 * import { productEntity } from './entities/product';
 *
 * // Validate create data
 * const result = validateEntity(productEntity, formData, 'create');
 *
 * if (result.success) {
 *   await saveProduct(result.data);
 * } else {
 *   console.error('Validation failed:', result.issues);
 *   // [{ path: 'name', message: 'Required' }, ...]
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Use in form submission
 * const onSubmit = async (data: unknown) => {
 *   const validation = validateEntity(productEntity, data, 'create');
 *
 *   if (!validation.success) {
 *     validation.issues?.forEach(issue => {
 *       form.setError(issue.path, { message: issue.message });
 *     });
 *     return;
 *   }
 *
 *   await api.createProduct(validation.data);
 * };
 * ```
 *
 * @see {@link Entity} for entity definition structure
 * @see {@link ValidationResult} for return type
 *
 * @version 0.1.0
 * @since 0.0.1
 * @author AMBROISE PARK Consulting
 */
export declare function validateEntity<E extends AnyEntity>(entity: E, data: unknown, operation?: SchemaOperation): ValidationResult<Record<string, unknown>>;

RenderableField:
/** Field with computed editability for rendering */
export interface RenderableField<T extends FieldType = FieldType> {
    /** Field name/key */
    name: string;
    /** Field configuration */
    config: EntityField<T>;
    /** Whether field is editable (input vs read-only) */
    editable: boolean;
    /**
     * Whether the form writes the field: an input (`editable`) or a derived
     * (`editable: 'computed'`) field. Its value lives in form state; a field the form
     * does not write (technical, `editable: false`, role-denied) is read from
     * `form.record`.
     * @since 0.2.5
     */
    written: boolean;
    /**
     * Values the field's `conditions` read: the key of a 1:1 extension (`offer`)
     * for its prefixed fields (`offer.priceExclVat`); omitted for the entity's own.
     * @since 0.2.5
     */
    scope?: string;
}

GetFieldsForOperationOptions:
/** Options for field filtering */
export interface GetFieldsForOperationOptions {
    /** Form operation type */
    operation: 'create' | 'edit';
    /** Viewer role for editability checks (defaults to 'guest' if undefined) */
    viewerRole?: string;
    /**
     * Available field names (for edit mode).
     * When provided, only fields in this list are returned.
     * Typically comes from Object.keys(defaultValues) - backend-filtered data.
     */
    availableFields?: string[];
}

SchemaOperation:
/**
 * Validation operation type
 */
export type SchemaOperation = 'create' | 'draft' | 'update' | 'full';

ValidationIssue:
/**
 * Validation issue structure
 */
export interface ValidationIssue {
    /** Field path (e.g., 'name' or 'address.street') */
    path: string;
    /** Error message */
