UseCrudReturn:
/**
 * CRUD API return type - Single Document & Actions
 */
export interface UseCrudReturn<T extends Record<string, unknown>> extends CrudAPI<T> {
    /**
     * Bulk write — inserts + updates + deletes in one adapter call. Partial
     * success: rows that are written stay written; rows that fail are listed in
     * `result.failed` (with the reason) and only they are reverted in the cache.
     * One audit entry, one rate-limit hit, one toast. Throws `BulkCollisionError`
     * when the payload carries the same id in two mutually-exclusive buckets.
     *
     * @example
     * ```tsx
     * const { bulk } = useCrud<Event>(eventEntity);
     * await bulk({ inserts, updates, deletes });
     * ```
     */
    bulk: (ops: BulkOperations<T>, options?: MutationOptions) => Promise<BulkResult>;
    /**
     * Ordered cross-collection bulk write, NOT a database transaction. Does NOT
     * require the hook's own entity to be one of the collections. Each batch
     * carries its own schemas. One optimistic pass, writes in topological waves.
     * Failure stops subsequent waves after all started writes settle, reverts
     * optimistic state, then refetches. Committed rows survive; the call rejects.
     *
     * @example
     * ```tsx
     * const { bulkAcross } = useCrud(customerEntity);
     * const customerId = generateUUID();
     * await bulkAcross([
     *   { collection: 'customers', inserts: [{ id: customerId, ...customerData }], schemas: { create: customerSchema } },
     *   { collection: 'inquiries', inserts: [{ customerId, ...inquiryData }], schemas: { create: inquirySchema }, dependsOn: ['customers'] },
     * ]);
     * ```
     */
    bulkAcross: (batches: BulkAcrossBatch[], options?: BulkAcrossOptions) => Promise<BulkAcrossResult>;
    /** @internal Collection name */
    _collection: string;
    /** @internal Generated schemas */
    _schemas: OperationSchemas | undefined;
    /** @internal Cache options */
    _cacheOptions: CacheOptions;
    /** @internal Scope configuration (for multi-tenancy) */
    _scope: ScopeConfig | undefined;
}

